<?php require_once __DIR__.'/includes/auth.php';customer_required();$items=cart_products($pdo);if(!$items)redirect('cart.php');$total=cart_total($pdo);$u=customer_user();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['shipping_name']??'');$phone=trim($_POST['shipping_phone']??'');$address=trim($_POST['shipping_address']??'');$method=$_POST['payment_method']??'cod';if(!$name||!$phone||!$address||!in_array($method,['cod','bank','jazzcash'],true))$error='Please complete all delivery and payment fields.';else{try{$pdo->beginTransaction();foreach($items as $p){$lock=$pdo->prepare('SELECT stock FROM products WHERE id=? FOR UPDATE');$lock->execute([$p['id']]);if((int)$lock->fetchColumn()<$p['qty'])throw new RuntimeException($p['name'].' does not have enough stock.');}$ins=$pdo->prepare('INSERT INTO orders(user_id,total,status,payment_method,payment_status,shipping_name,shipping_phone,shipping_address) VALUES(?,?,"pending",?,"pending",?,?,?)');$ins->execute([$_SESSION['user_id'],$total,$method,$name,$phone,$address]);$oid=(int)$pdo->lastInsertId();$oi=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)');$up=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');foreach($items as $p){$oi->execute([$oid,$p['id'],$p['name'],$p['price'],$p['qty']]);$up->execute([$p['qty'],$p['id']]);}$pdo->commit();if($method==='jazzcash'){$_SESSION['payment_order']=$oid;redirect('payment/jazzcash_start.php?order_id='.$oid);}$_SESSION['cart']=[];redirect('order_success.php?id='.$oid);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}}$page_title='Checkout — MediNova';require __DIR__.'/includes/store_header.php';?><section class="form-page"><div class="form-shell"><p class="kicker">SECURE CHECKOUT</p><h1>Almost there.</h1><?php if($error):?><div class="admin-alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-row"><div class="field"><label>Full name</label><input name="shipping_name" value="<?=e($u['name'])?>" required></div><div class="field"><label>Phone</label><input name="shipping_phone" value="<?=e($u['phone']??'')?>" required></div></div><div class="field"><label>Delivery address</label><textarea name="shipping_address" rows="4" required></textarea></div><div class="field"><label>Payment method</label><div class="payment-choice"><label><input type="radio" name="payment_method" value="cod" checked> Cash on Delivery<br><small>Pay when your order arrives.</small></label><label><input type="radio" name="payment_method" value="bank"> Bank Transfer<br><small>Manual confirmation by admin.</small></label><label><input type="radio" name="payment_method" value="jazzcash"> JazzCash Online<br><small>Redirect to JazzCash hosted checkout.</small></label></div></div><div class="order-summary"><div><span>Products</span><span><?=cart_count()?></span></div><div class="grand"><span>Total</span><strong>Rs. <?=number_format($total)?></strong></div></div><button class="btn btn-light" style="margin-top:25px">Place order & continue ↗</button></form></div></section><?php require __DIR__.'/includes/store_footer.php'; ?>
